import {seasons,endings,choiceLabel,resolveEnding,endingText,statusFor} from './model.mjs';
import {cleanState,freshState} from './state.mjs';
import * as cloud from './cloud.mjs';
import * as music from './music.mjs';
import {regions,worldSVG,paintedWorldAssets} from './world.mjs';
import {createMission,mountMission,missionInfo} from './missions.mjs';
import {destinations,homePoint,project,route,directionalTarget,pathSVG,distance} from './navigation.mjs';
import {setting,arrivals,storyCards,calendar,transition,typeText} from './story.mjs';
import {photo} from './effects.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const H=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const spots=destinations,icons=['🌳','💧','🌾','🏮'];
const planSentences=[['도로를 짧게 연결해서 숲을 가로지른다.','새 도로 대신 원래 있던 길로 돌아간다.','동물의 이동을 조사하고 안전한 통로를 만든다.','숲 일부를 정리하고 꽃밭으로 꾸민다.'],['작업장의 물 처리 시설을 고치고 계속 점검한다.','하천에 떠 있는 쓰레기를 건져 낸다.','가림막과 조명을 설치해서 물가를 꾸민다.','시설 수리·청소·꾸미기에 돈을 조금씩 나눈다.'],['전문가와 피해 입은 잎을 살피고 필요한 곳만 관리한다.','농장 전체에 농약을 뿌린다.','작물과 풀을 없애고 한 종류의 꽃을 심는다.','작물 사진을 찍으며 관리하지 않고 기다린다.'],['컵을 돌려받고 쓰레기를 분리하며 낮 조명을 끈다.','행사가 끝난 뒤 바닥을 한 번 청소한다.','일회용 컵을 넉넉히 쌓고 축제 조명을 켠다.','모은 쓰레기를 불에 태워 처리한다.']];
const planText=(i,id)=>planSentences[i][seasons[i].choices.findIndex(c=>c.id===id)];
let walkFrame=0,stopStory=()=>{},dialogueTyping=null,arrivalSeen=new Set(),titleSeen=new Set(),travelBusy=false;
let key='eco-village-guest-v2',state=readLocal(),selected=null,mission=null,stopMission=()=>{},toastTimer,cinemaTimer,cloudStatus='guest',booting=cloud.configured,viewMode='auto',pastChapter=null;
function readLocal(){try{return cleanState(JSON.parse(localStorage.getItem(key)||'null'));}catch{return freshState();}}
function writeLocal(){try{localStorage.setItem(key,JSON.stringify(state));if(cloud.account())localStorage.setItem(key+'-base',String(cloud.version()));}catch{toast('기기 저장 공간이 부족해요.');}}
function save(){state.updatedAt=Date.now();writeLocal();cloud.queueCloud(state);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400);}
function reset(){stopMission();stopMission=()=>{};selected=null;mission=null;}
const g=()=>state.game, count=()=>Object.keys(state.album).length;
function header(){const a=cloud.account(),stage=g()?.stage;return `<header class="topbar"><button class="logo" id="home" aria-label="처음 화면"><span class="brand-star">✦</span><span><b>초록마을</b><small>네 계절의 생태 이야기</small></span></button><nav class="seasons" aria-label="계절 진행"><small class="season-caption">${stage===4?'다음 봄을 앞두고':stage===undefined?'FOUR SEASONS':seasons[stage].month+' · '+seasons[stage].title}</small><div>${seasons.map((s,i)=>`<span class="season ${stage===i?'active':''} ${g()?.choices[i]?'complete':''}" ${stage===i?'aria-current="step"':''}>${s.name}${g()?.choices[i]?' ✓':''}</span>`).join('')}</div></nav><div class="top-actions">${musicUI()}<button id="save-cloud" class="save-state" title="진행 기록 저장">${cloudLabel()}</button><button id="account" class="icon-button" aria-label="학교 계정">${a?H(a.nickname||'주민'):'학교 계정'}</button><button id="album" class="icon-button" aria-label="엔딩 앨범">▤ ${count()}/10</button><button id="help" class="icon-button" aria-label="게임 방법">?</button></div></header>`;}
function cloudLabel(){return ({guest:'기기에 저장',online:'온라인 연결',saved:'☁ 저장 완료',pending:'☁ 저장 대기',saving:'☁ 저장 중',error:'☁ 다시 저장',conflict:'☁ 다른 기기 기록'})[cloudStatus]||'기기에 저장';}
function musicUI(){return `<span class="music-controls"><button class="icon-button music-toggle" data-music-toggle aria-label="배경음악 켜기" aria-pressed="false" title="배경음악 켜기">🔇</button><button class="icon-button music-settings" data-music-settings aria-label="배경음악 음량 설정" title="배경음악 음량 설정">♫</button></span>`;}
function updateMusic(){const s=music.status();$$('[data-music-toggle]').forEach(b=>{b.textContent=s.loading?'…':s.enabled?'🔊':'🔇';b.setAttribute('aria-pressed',String(s.enabled));b.setAttribute('aria-label',s.enabled?'배경음악 끄기':'배경음악 켜기');b.title=s.enabled?'배경음악 끄기':'배경음악 켜기';});const v=$('#music-volume-label');if(v)v.textContent=Math.round(s.volume*100)+'%';const t=$('#music-title');if(t)t.textContent=s.loading?'음악을 준비하고 있어요…':s.enabled?s.title:'배경음악이 꺼져 있어요.';}
function bindMusic(){updateMusic();$$('[data-music-toggle]').forEach(b=>b.onclick=()=>music.setEnabled(!music.status().enabled).catch(()=>toast('음악을 불러오지 못했어요. 소리 버튼을 다시 눌러 주세요.')));$$('[data-music-settings]').forEach(b=>b.onclick=musicDialog);}
function musicDialog(){const s=music.status();modal('♫ 마을의 배경음악',`<div class="music-panel"><p id="music-title">${s.enabled?s.title:'배경음악이 꺼져 있어요.'}</p><button class="secondary" data-music-toggle aria-label="배경음악 켜기"></button><label for="music-volume">음량 <strong id="music-volume-label">${Math.round(s.volume*100)}%</strong></label><input id="music-volume" type="range" min="0" max="100" step="5" value="${Math.round(s.volume*100)}" aria-label="배경음악 음량"><p class="small-note">소리 버튼으로 켜고 끌 수 있어요. 음량은 이 기기에 기억해요.<br>새로 열면 소리는 꺼져 있어요.</p><p class="small-note">마을과 엔딩을 위해 직접 만든 무료 곡이에요.<br>「초록마을 산책」 · 「우리의 다음 봄」 · 「돌아오지 않는 봄」</p></div>`);bindMusic();$('#music-volume').oninput=e=>music.setVolume(Number(e.target.value)/100);}
music.subscribe(updateMusic);
function bindHeader(){bindMusic();$('#home').onclick=home;$('#album').onclick=openAlbum;$('#help').onclick=help;$('#account').onclick=accountDialog;$('#save-cloud').onclick=async()=>{if(!cloud.account()){accountDialog();return;}if(cloudStatus==='conflict'){conflictDialog();return;}try{cloud.queueCloud(state);await cloud.flushCloud();toast('온라인에 저장했어요. 다른 기기에서도 이어 할 수 있어요.');}catch{toast('연결을 확인해 주세요. 기기 기록은 남아 있어요.');}};}
function home(){document.body.dataset.screen='home';cancelAnimationFrame(walkFrame);stopStory();dialogueTyping?.stop();stopMission();pastChapter=null;viewMode='auto';music.setScene('village');clearInterval(cinemaTimer);$('.cinema')?.remove();$('#dialog').close();$('#app').innerHTML=header()+`<main class="home-screen"><div class="home-art"></div><section class="welcome parchment"><span class="eyebrow">GREEN VILLAGE · ECO ADVENTURE</span><h1>초록마을의<br><em>네 계절</em></h1><div class="title-rule"></div><p>작은 마을의 새 주민이 된 당신.<br>숲과 하천, 농장과 축제를 걸으며<br>우리의 다음 봄을 만들어 보세요.</p><div class="welcome-badges"><span>네 계절의 선택</span><span>10개의 엔딩</span></div><div class="welcome-actions">${g()?'<button class="primary" id="continue">모험 이어 하기</button>':''}<button class="${g()?'secondary':'primary'}" id="new-game">마을로 출발</button><button class="text-button" id="login-start">학교 계정으로 기록 남기기</button></div><small>길 클릭 · 방향키로 이동 &nbsp; E 대화 · J 수첩<br>다른 선택으로 새로운 엔딩을 모아 보세요.</small></section><div class="home-note">네 번의 계절, 당신이 바꿀 마을.</div></main>`;bindHeader();$('#new-game').onclick=()=>start(0);$('#login-start').onclick=accountDialog;if($('#continue'))$('#continue').onclick=()=>{if(g().stage<4&&g().phase==='task'&&!arrivalSeen.has(g().stage)){viewMode='map';render();enterChapter();}else render();};if(booting){$('#new-game').disabled=true;if($('#continue'))$('#continue').disabled=true;}}
function start(stage){if(booting){toast('기록을 확인하고 있어요. 잠시만 기다려 주세요.');return;}clearInterval(cinemaTimer);$('.cinema')?.remove();$('#dialog').close();const previous=state.last;if(stage&& !previous){toast('먼저 한 판을 끝내 주세요.');return;}stopStory();arrivalSeen=new Set();titleSeen=new Set();viewMode='map';pastChapter=null;state.game={stage,choices:stage?previous.choices.map((v,i)=>i<stage?v:null):[null,null,null,null],phase:'explore',player:[...homePoint]};reset();save();render();if(stage===0)stopStory=storyCards(setting);}
function playerHTML(){return `<div class="explorer" id="explorer" style="left:${g().player[0]}%;top:${g().player[1]}%" role="img" aria-label="내 캐릭터"><span class="explorer-hair"></span><span class="explorer-face"></span><span class="explorer-shirt"></span><span class="explorer-feet"></span><span class="explorer-name">${H(cloud.account()?.nickname||'나')}</span></div>`;}
function mapHTML(){
  const current=Math.min(g().stage,3),s=seasons[current],done=g().stage===4,recorded=g().choices.filter(Boolean).length;
  const destination=done?'마을 회의':s.area+' · '+s.speaker,action=done?'마을 회의 참석':g().phase==='result'?'선택이 남긴 변화 보기':s.speaker+' 만나기';
  return `<section class="map-frame" aria-label="초록마을 이동 지도"><div class="world-plane">${worldSVG({choices:g().choices,stage:g().stage})}${pathSVG()}<div class="map-glow"></div>${seasons.map((season,i)=>`<button class="village-spot ${i===current&&!done?'current':''} ${g().choices[i]?'recorded':''}" data-spot="${i}" style="left:${spots[i][0]}%;top:${spots[i][1]}%" ${!g().choices[i]&&i!==g().stage?'disabled':''} aria-label="${season.area} · ${season.speaker}${g().choices[i]?' · 기록 다시 보기':i===g().stage?' 만나기':' · 다음 계절'}"><strong>${season.area} · ${season.speaker}</strong><small>${g().choices[i]?'방문 기록':i===current?'이야기 듣기':'다음 계절'}</small>${g().choices[i]?'<i>✓</i>':i===current?'<i>!</i>':''}</button>`).join('')}${playerHTML()}</div><aside class="field-journal"><span class="eyebrow">${done?'우리의 네 계절':'이번 계절의 현장 기록'}</span><h2>${done?'다음 봄을 앞두고':s.title}</h2><p>${done?'함께 고른 네 가지 방법을 돌아보고, 마을의 다음 봄을 만나 보세요.':s.area+'에서 기다리는 '+s.speaker+'의 이야기를 듣고, 마을을 위한 방법을 골라 보세요.'}</p><div class="field-progress">남긴 계절 기록 <b>${recorded} / 4</b></div><button id="journal" class="journal-button">▤ 조사 수첩 <span>${recorded}</span></button></aside><div class="map-name"><b>초록마을 · ${done?'마을 회의':s.area}</b><small>${done?'겨울의 마지막 기록':s.month+' · '+s.name+'의 이야기'}</small></div><div class="village-mini" aria-label="마을 전체 지도"><div class="mini-world">${worldSVG({choices:g().choices,stage:g().stage,instance:'mini'})}<span class="mini-player" style="left:${g().player[0]}%;top:${g().player[1]}%"></span></div><small>초록마을</small></div><div class="map-dock"><div class="arrows" aria-label="캐릭터 이동"><button data-move="up" aria-label="위로 이동">▲</button><button data-move="left" aria-label="왼쪽 이동">◀</button><button data-move="down" aria-label="아래로 이동">▼</button><button data-move="right" aria-label="오른쪽 이동">▶</button></div><span class="movement-tip"><kbd>WASD</kbd> / 방향키 이동 &nbsp; <kbd>E</kbd> 대화 &nbsp; <kbd>J</kbd> 수첩</span></div><div class="travel-guide"><small>${destination}</small><button id="enter-chapter" class="primary">${action} →</button></div></section>`;
}
function render(){
  cancelAnimationFrame(walkFrame);dialogueTyping?.stop();stopMission();
  if(!g()){home();return;}
  music.setScene('village');clearInterval(cinemaTimer);$('.cinema')?.remove();
  const chapter=viewMode==='chapter'||(viewMode==='auto'&&g().phase!=='explore');
  document.body.dataset.screen=chapter?'chapter':'map';
  $('#app').innerHTML=header()+`<main class="${chapter?'chapter-screen':'travel-screen'}">${chapter?chapterHTML():mapHTML()}</main>`;
  bindHeader();
  if(chapter){$('#back-map').onclick=()=>transition(()=>{viewMode='map';pastChapter=null;render();});renderQuest();}
  else {g().player=project(g().player).point;const p=$('#explorer');p.style.left=g().player[0]+'%';p.style.top=g().player[1]+'%';bindMap();}
}
function chapterHTML(){
  const i=pastChapter??Math.min(g().stage,3),s=seasons[i],isResult=pastChapter!==null||g().phase==='result',meeting=g().stage===4&&pastChapter===null;
  return `<section class="chapter-scene" aria-label="${s.area}의 배경">${worldSVG({choices:g().choices,chapter:meeting?null:i,stage:g().stage})}</section><div class="chapter-banner"><small>${meeting?'네 계절의 마지막 장':'CHAPTER '+(i+1)+' · '+s.name.toUpperCase()}</small><h1>${meeting?'마을 회의':regions[i].name}</h1><p>${pastChapter!==null?'내 선택이 남긴 풍경':s.month+' · '+s.speaker+'의 이야기'}</p></div><button class="chapter-back" id="back-map">↖ 전체 지도로</button><div id="route-work"></div><section class="quest parchment ${isResult?'result-panel':meeting?'final-panel':''}" id="quest" aria-label="${meeting?'마을 회의':s.speaker+'의 대화와 선택'}"></section>`;
}
async function enterChapter(i=g().stage,past=false){
  if(travelBusy)return;travelBusy=true;
  const first=!past&&g().stage<4&&g().phase!=='result'&&!arrivalSeen.has(i);
  await transition(()=>{pastChapter=past?i:null;viewMode='chapter';if(!past&&g().phase==='explore'){g().player=[...spots[i]];g().phase='task';save();}render();});
  travelBusy=false;
  if(first){arrivalSeen.add(i);const tell=()=>{stopStory=storyCards(arrivals[i],()=>renderQuest());};if(titleSeen.has(i))tell();else{titleSeen.add(i);stopStory=calendar(seasons[i],i,tell);}}
}
function bindMap(){
  $$('[data-spot]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.spot);if(g().choices[i]||i===g().stage)moveTo(...spots[i],()=>enterChapter(i,!!g().choices[i]&&i!==g().stage));else toast('지금은 '+seasons[g().stage].name+'이에요. 기다리는 주민부터 만나 주세요.');});
  $('.world-plane').onclick=e=>{if(e.target.closest('button'))return;const r=e.currentTarget.getBoundingClientRect();moveTo((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100);};
  $$('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));$('#journal').onclick=journal;$('#enter-chapter').onclick=()=>{if(g().stage===4)enterChapter();else moveTo(...spots[g().stage],()=>enterChapter());};
}
function moveTo(x,y,onArrival){
  const p=$('#explorer');if(!p||travelBusy)return;cancelAnimationFrame(walkFrame);
  const steps=route(g().player,[x,y]);let segment=1,last=0;
  const trail=$('#walk-route');if(trail)trail.setAttribute('d',steps.map((a,i)=>(i?'L':'M')+a.join(',')).join(' '));p.classList.add('walking');
  const finish=()=>{p.classList.remove('walking');if(trail)trail.setAttribute('d','');writeLocal();onArrival?.();};
  if(steps.length<2){finish();return;}
  const tick=time=>{if(!p.isConnected)return;let amount=last?Math.min(1,(time-last)/1000)*17:0;last=time;
    while(segment<steps.length&&amount>=0){const target=steps[segment],d=distance(g().player,target);if(d<=amount+.001){g().player=[...target];amount-=d;segment++;}else{const t=amount/d;g().player=[g().player[0]+(target[0]-g().player[0])*t,g().player[1]+(target[1]-g().player[1])*t];break;}}
    p.style.left=g().player[0]+'%';p.style.top=g().player[1]+'%';const marker=$('.mini-player');if(marker){marker.style.left=g().player[0]+'%';marker.style.top=g().player[1]+'%';}if(segment===steps.length)finish();else walkFrame=requestAnimationFrame(tick);
  };walkFrame=requestAnimationFrame(tick);
}
function move(direction){if(g()&&viewMode!=='chapter'&&!travelBusy){const next=directionalTarget(g().player,direction);moveTo(...next);}}
document.addEventListener('keydown',e=>{if($('#dialog').open||$('.cinema')||$('.story-overlay')||$('.calendar-overlay')||!g()||e.target.matches('input,textarea,select,[contenteditable]'))return;if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='j'){e.preventDefault();journal();return;}if(e.key.toLowerCase()==='e'&&viewMode!=='chapter'){e.preventDefault();const i=Math.min(g().stage,3);if(g().stage===4||distance(g().player,spots[i])<=6)enterChapter();else toast(seasons[i].area+'의 주민에게 다가가거나 아래 만나기 버튼을 눌러 주세요.');return;}const dir=({ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down'})[e.key];if(dir){e.preventDefault();move(dir);}});
function renderQuest(){
  const i=pastChapter??Math.min(g().stage,3),s=seasons[i],q=$('#quest');
  if(pastChapter!==null){const c=s.choices.find(c=>c.id===g().choices[i]);q.classList.add('result-panel');q.innerHTML=`<span class="quest-tag">${s.name}에 남긴 기록</span><h2>${H(planText(i,c.id))}</h2><p class="result-text">${H(c.result)}</p><button class="primary" id="return-map">전체 지도 보기</button>`;$('#return-map').onclick=()=>transition(()=>{viewMode='map';pastChapter=null;render();});return;}
  if(g().stage===4||g().phase==='final'){q.classList.add('final-panel');final();return;}
  if(g().phase==='result'){
    const c=s.choices.find(c=>c.id===g().choices[g().stage]);q.classList.add('result-panel');
    q.innerHTML=`<span class="quest-tag">${s.speaker} · 선택이 남긴 변화</span><h2>${H(planText(i,c.id))}</h2><p class="result-text">${H(c.result)}</p><button class="secondary" id="see-world">바뀐 전체 지도 보기</button><button class="primary" id="next">${g().stage===3?'마을 회의로':'다음 계절로'}</button>`;
    $('#see-world').onclick=()=>transition(()=>{viewMode='map';render();});$('#next').onclick=()=>transition(()=>{g().stage++;g().phase=g().stage===4?'final':'explore';viewMode=g().stage===4?'chapter':'map';pastChapter=null;reset();save();render();if(g().stage<4){titleSeen.add(g().stage);stopStory=calendar(seasons[g().stage],g().stage,()=>{});}});return;
  }
  stopMission();q.classList.remove('result-panel','final-panel','mission-panel');
  if(selected){
    mission ||= createMission(i,selected);const info=missionInfo(i,selected),plan=s.choices.find(c=>c.id===selected);
    q.classList.add('mission-panel');
    q.innerHTML=`<div class="quest-heading"><span class="speaker-badge">${info.icon}</span><div><span class="quest-tag">${s.speaker}</span><h2>${info.title}</h2><small class="mission-plan-name">${H(planText(i,plan.id))}</small></div></div><p class="dialogue"><span class="mission-character">${['🧑‍🌾','🧑‍🔧','🧑‍🌾','🧑‍🎤'][i]}</span>“${info.goal}”</p><div class="task-area"><div id="work"></div></div><div class="quest-footer"><p id="task-note"></p><div><button class="secondary" id="plan-back">다시 고르기</button><button class="secondary" id="reset-mission">미션 다시 하기</button><button class="primary" id="commit" disabled>작업 마치기</button></div></div>`;
    $('#plan-back').onclick=()=>{reset();renderQuest();};$('#reset-mission').onclick=()=>{stopMission();mission=createMission(i,selected);renderQuest();};$('#commit').onclick=commit;
    stopMission=mountMission($('#work'),mission,done=>{if(!$('#commit'))return;$('#commit').disabled=!done;$('#task-note').textContent=done?'일을 마쳤어요.':'';$('#reset-mission').hidden=done;});return;
  }
    q.innerHTML=`<div class="quest-heading"><span class="speaker-badge">${icons[i]}</span><div><span class="quest-tag">${s.month} · ${s.speaker}</span><h2>${s.title}</h2></div></div><div class="dialogue villager-dialogue"><span class="dialogue-portrait"><span class="villager-head"></span><span class="villager-body"></span></span><p id="villager-line"></p><button class="text-button" id="read-line">대화 계속 →</button></div><div class="task-area"><div class="choices" hidden>${s.choices.map((c,j)=>`<button class="choice" data-plan="${c.id}"><span>${j+1}</span><strong>${planSentences[i][j]}</strong></button>`).join('')}</div></div>`;
  const reveal=()=>{$('.choices').hidden=false;$('#read-line').hidden=true;};
  dialogueTyping=typeText($('#villager-line'),s.line,reveal);$('#read-line').onclick=()=>dialogueTyping.finish();
  $$('[data-plan]').forEach(b=>b.onclick=()=>{dialogueTyping?.stop();selected=b.dataset.plan;mission=createMission(i,selected);const painting=new Image();painting.src=paintedWorldAssets[i];renderQuest();});

}
function commit(){
  if(!mission?.done||mission.stage!==g().stage||mission.id!==selected||!seasons[g().stage].choices.some(c=>c.id===selected))return;
  const before=[...g().choices],i=g().stage;stopMission();g().choices[i]=selected;g().phase='result';save();render();const scene=$('.chapter-scene'),old=document.createElement('div');old.className='previous-scene';old.innerHTML=worldSVG({choices:before,chapter:i,stage:i,instance:'before'});scene.append(old);const buttons=$$('#quest button');buttons.forEach(b=>b.disabled=true);requestAnimationFrame(()=>requestAnimationFrame(()=>old.classList.add('dissolving')));setTimeout(()=>{old.remove();if(scene.isConnected)buttons.forEach(b=>b.disabled=false);},1900);
}
function final(){const q=$('#quest');q.classList.add('meeting-records');q.innerHTML=`<span class="quest-tag">冬 · 겨울의 마지막 기록</span><h2>우리가 고른 네 계절</h2><div class="meeting-journal">${seasons.map((s,i)=>`<p><b>${icons[i]} ${s.name}</b><span>${H(planText(i,g().choices[i]))}</span></p>`).join('')}</div><button class="primary" id="attend-meeting">마을 회의 참석하기 →</button>`;$('#attend-meeting').onclick=()=>{q.classList.remove('meeting-records');q.innerHTML=`<span class="quest-tag">겨울의 마지막 회의</span><h2>다음 봄을 앞두고</h2><p>“네 계절 동안 함께 준비해 주어서 고마워요.<br>우리가 고른 방법을 앞으로도 이어 갈까요?”</p><div class="final-choices"><button id="keep"><strong>지금 계획대로 진행한다.</strong></button><button id="repair"><strong>담당 어른들과 문제가 된 방법을 고친다.</strong></button></div><button class="text-button" id="final-journal">내 선택 기록 보기</button>`;$('#keep').onclick=()=>finish(false);$('#repair').onclick=()=>finish(true);$('#final-journal').onclick=journal;};}

function finish(repair){const choices=[...g().choices],id=resolveEnding(choices,repair),fresh=!state.album[id];state.album[id]={choices,repair};state.last={choices,repair};state.game=null;save();cinema({id,choices,repair},fresh);}
function modal(title,html){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button id="close" aria-label="닫기">×</button></div><div class="dialog-body">${html}</div>`;$('#close').onclick=()=>d.close();if(!d.open)d.showModal();return d;}
function recordDialog(i){if(!g()?.choices[i])return;const s=seasons[i],c=s.choices.find(c=>c.id===g().choices[i]);modal(`${icons[i]} ${s.name}의 기록`,`<p class="record-date">${s.month} · ${s.area}</p><h3>${c.name}</h3><p>${c.result}</p>`);if(c.id==='wait')savedPhotos();}
function savedPhotos(){const d=$('#dialog'),strip=document.createElement('div');strip.className='saved-photos';strip.setAttribute('aria-label','작물 관찰 사진');d.querySelector('.dialog-body').append(strip);for(let i=0;i<3;i++)photo(i).then(src=>{if(!strip.isConnected)return;const image=document.createElement('img');image.src=src;image.alt='가을에 남긴 작물 사진 '+(i+1);strip.append(image);}).catch(()=>{});}
function journal(){const a=g()?.choices||state.last?.choices||[null,null,null,null];modal('🎒 내 모험 기록',`<div class="journal-pages">${seasons.map((s,i)=>`<button class="journal-entry ${a[i]?'written':''}" data-record="${i}"><span>${icons[i]}</span><div><strong>${s.name} · ${s.area}</strong><p>${a[i]?planText(i,a[i]):'아직 기록하지 않았어요.'}</p></div></button>`).join('')}</div>`);$$('[data-record]').forEach(b=>b.onclick=()=>{if(g()?.choices[b.dataset.record])recordDialog(Number(b.dataset.record));else if(a[b.dataset.record]){const i=Number(b.dataset.record),c=seasons[i].choices.find(c=>c.id===a[i]);modal(`${icons[i]} ${seasons[i].name}의 기록`,`<h3>${c.name}</h3><p>${c.result}</p>`);if(c.id==='wait')savedPhotos();}});}
function openAlbum(page=0){page=page===1?1:0;modal(`📖 엔딩 앨범 ${count()}/10`,`<p class="album-lead">다른 선택으로 새로운 이야기를 찾아보세요.</p><div class="album-grid">${endings.slice(page*5,page*5+5).map(e=>`<button class="ending-card ${state.album[e.id]?'found':'locked'}" data-ending="${e.id}"><span>${state.album[e.id]?'✦':'🔒'}</span><small>${e.id}</small><strong>${state.album[e.id]?e.title:'아직 펼치지 않은 이야기'}</strong></button>`).join('')}</div><div class="album-nav"><button id="prev" ${page===0?'disabled':''}>◀ 앞장</button><span>${page+1}/2</span><button id="next-page" ${page===1?'disabled':''}>다음 장 ▶</button></div>`);$('#prev').onclick=()=>openAlbum(0);$('#next-page').onclick=()=>openAlbum(1);$$('[data-ending]').forEach(b=>b.onclick=()=>albumDetail(b.dataset.ending));}
function albumDetail(id){const e=endings.find(e=>e.id===id),r=state.album[id];modal(`${id} · ${r?e.title:'새 엔딩의 단서'}`,`<p>${r?'이 이야기를 이미 발견했어요. 영화처럼 다시 볼 수 있어요.':state.last?e.hint:'첫 모험을 마치면 새 이야기의 단서를 볼 수 있어요.'}</p>${r?'<button class="primary" id="rewatch">엔딩 다시 보기</button>':''}${state.last?`<div class="replay-buttons">${seasons.map((s,i)=>`<button data-restart="${i}">${s.name}부터 다시</button>`).join('')}</div><p class="small-note">가장 최근에 끝낸 판의 앞선 선택을 남겨 둬요.</p>`:''}<button class="text-button" id="album-back">앨범으로 돌아가기</button>`);if(r)$('#rewatch').onclick=()=>cinema({id,...r});$('#album-back').onclick=()=>openAlbum(id>'E05'?1:0);$$('[data-restart]').forEach(b=>b.onclick=()=>start(Number(b.dataset.restart)));}
function cinema(r,fresh=false){
  clearInterval(cinemaTimer);$('#dialog').close();$('.cinema')?.remove();
  const e=endings.find(e=>e.id===r.id),lines=endingText(r.id,r.choices);music.setScene(e.tone);
  const c=document.createElement('section');c.className='cinema '+e.tone;
  c.innerHTML=`<div class="cinema-top"><span>초록마을 · 다음 봄</span><div>${musicUI()}${r.choices[2]==='wait'?'<button id="ending-photos">관찰 사진</button>':''}<button id="cinema-save" data-cloud-status title="다른 기기로 이동하기 전에 눌러 주세요">${cloudLabel()}</button><button class="cinema-world-toggle" id="ending-world-toggle">마을만 크게 보기</button><button id="pause">잠깐 멈춤</button><button id="speed">빠르게</button><button id="all">전체 보기</button><button id="type">크레딧 다시 보기</button></div></div><div class="cinema-body"><section class="ending-world" aria-label="이 엔딩에서 내가 만든 마을"><div class="ending-world-label"><strong>내 선택이 남긴 초록마을</strong><small>${r.repair?'뒤늦은 대책도 피해를 모두 지우지는 못해요':'네 계절 동안 바뀐 풍경'}</small></div><div class="ending-world-map"><div class="world-plane">${worldSVG({choices:r.choices,ending:true,repair:r.repair,stage:4})}</div></div><div class="ending-world-records">${seasons.map((s,i)=>`<span><strong>${icons[i]} ${s.area}</strong>${choiceLabel(i,r.choices[i])}</span>`).join('')}</div></section><div class="credits-window" id="credits-window"><div class="credits"><small>ENDING ${r.id.slice(1)} / 10</small><h1>${e.title}</h1><div id="lines"></div></div></div></div><div class="cinema-bottom"><div><strong>${fresh?'새 엔딩을 발견했어요!':'다시 만난 이야기'} · ${count()}/10</strong><small>기기에 기록했어요. 기기를 바꾸기 전 ☁ 저장 버튼을 눌러 주세요.</small></div><button id="cinema-album">📖 엔딩 앨범</button><button class="primary" id="replay">다른 선택 해보기</button></div>`;
  document.body.append(c);bindMusic();if($('#ending-photos'))$('#ending-photos').onclick=()=>{modal('가을에 남긴 관찰 사진','<p>관리를 기다리며 기록한 세 곳의 모습이에요.</p>');savedPhotos();};$('#cinema-save').onclick=()=>$('#save-cloud').click();
  $('#ending-world-toggle').onclick=()=>{const only=c.classList.toggle('map-only');$('#ending-world-toggle').textContent=only?'이야기 함께 보기':'마을만 크게 보기';};
  let paused=false,speed=1,lastTime=0,position=0;
  const win=$('#credits-window'),credits=win.querySelector('.credits');
  const roll=()=>{clearInterval(cinemaTimer);$('#lines').innerHTML=lines.map(s=>`<p>${H(s)}</p>`).join('');c.classList.add('rolling');c.classList.remove('credits-finished');win.scrollTop=0;position=win.clientHeight*.9;credits.style.transform=`translateY(${position}px)`;paused=false;speed=1;lastTime=performance.now();$('#pause').disabled=false;$('#speed').disabled=false;$('#pause').textContent='잠깐 멈춤';$('#speed').textContent='빠르게';
    cinemaTimer=setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-lastTime)/1000);lastTime=now;if(paused||$('#dialog').open||c.classList.contains('map-only'))return;position-=dt*22*speed;credits.style.transform=`translateY(${position}px)`;if(position<-(credits.offsetHeight-win.clientHeight*.35)){clearInterval(cinemaTimer);$('#pause').disabled=true;c.classList.add('credits-finished');}},30);
  };
  $('#type').onclick=roll;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'계속 읽기':'잠깐 멈춤';};$('#speed').onclick=()=>{speed=speed===1?2.5:1;$('#speed').textContent=speed===1?'빠르게':'천천히';};
  $('#all').onclick=()=>{clearInterval(cinemaTimer);c.classList.remove('rolling','credits-finished');credits.style.transform='';$('#lines').innerHTML=lines.map(s=>`<p>${H(s)}</p>`).join('');win.scrollTop=0;$('#pause').disabled=true;$('#speed').disabled=true;};$('#cinema-album').onclick=openAlbum;$('#replay').onclick=replayDialog;
  roll();
}
function replayDialog(){modal('어느 계절부터 바꿀까요?',`<p>이전 계절의 선택을 남기고 다시 해요.<br>처음부터 하려면 봄을 골라 주세요.</p><div class="replay-buttons">${seasons.map((s,i)=>`<button data-restart="${i}">${icons[i]} ${s.name}부터</button>`).join('')}</div><p class="small-note">수집한 엔딩은 계속 남아요.</p>`);$$('[data-restart]').forEach(b=>b.onclick=()=>start(Number(b.dataset.restart)));}
function accountDialog(){const a=cloud.account();if(a){modal('☁ 내 학교 계정',`<h3>${H(a.school)} · ${H(a.nickname)}</h3><p>${cloudStatus==='conflict'?'다른 기기에 더 최근 기록이 있어요. 불러오기로 확인해 주세요.':'기기에는 바로 저장하고, 온라인에는 10분마다 묶어 저장해요. 기기를 바꾸거나 수업을 마칠 때 지금 저장하기를 눌러 주세요.'}</p><div class="account-actions"><button class="primary" id="sync">지금 저장하기</button><button id="pull">온라인 기록 불러오기</button><button id="logout">저장하고 로그아웃</button></div><p class="form-error" id="account-error"></p>`);$('#sync').onclick=async()=>{try{cloud.queueCloud(state);await cloud.flushCloud();toast('온라인 저장 완료');$('#dialog').close();}catch(e){$('#account-error').textContent=cloud.authMessage(e);}};$('#pull').onclick=async()=>{const pending={...state};try{const remote=await cloud.loadCloud();state=remote;state.album={...pending.album,...remote.album};pastChapter=null;viewMode='auto';reset();save();$('#dialog').close();render();toast('온라인 기록을 불러왔어요.');}catch(e){$('#account-error').textContent=cloud.authMessage(e);}};$('#logout').onclick=async()=>{try{cloud.queueCloud(state);await cloud.signOut();$('#dialog').close();home();}catch(e){$('#account-error').textContent='온라인 저장이 안 되어 로그아웃을 멈췄어요. 연결을 확인해 주세요.';}};return;}
  modal('🌱 학교 계정으로 모험하기',`<div class="login-tabs"><button id="login-tab" class="active">로그인</button><button id="signup-tab">처음 가입</button></div><form id="login-form"><label>학교 이름<input name="school" autocomplete="organization" maxlength="60" minlength="2" required placeholder="예: 광주 초록초등학교"></label><label>닉네임<input name="nickname" autocomplete="username" maxlength="16" minlength="2" required placeholder="실명 대신 별명을 써 주세요"></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" minlength="8" maxlength="128" required placeholder="8자 이상"></label><p class="form-error" id="form-error"></p><button class="primary" type="submit" id="login-submit">로그인하고 이어 하기</button></form><p class="small-note">같은 학교·닉네임·비밀번호로 다른 기기에서도 이어 해요.<br>비밀번호를 기억해 두세요. 이메일은 받지 않아요.</p><button class="text-button" id="guest">계정 없이 체험하기</button>`);let create=false;$('#login-tab').onclick=()=>setMode(false);$('#signup-tab').onclick=()=>setMode(true);const setMode=v=>{create=v;$('#signup-tab').classList.toggle('active',v);$('#login-tab').classList.toggle('active',!v);$('#login-submit').textContent=v?'가입하고 모험 시작':'로그인하고 이어 하기';$('#login-form [name=password]').autocomplete=v?'new-password':'current-password';$('#form-error').textContent='';};$('#guest').onclick=()=>{$('#dialog').close();if(!g())start(0);};$('#login-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);$('#login-submit').disabled=true;$('#form-error').textContent='연결하는 중이에요…';try{await cloud.signIn({school:f.get('school'),nickname:f.get('nickname'),password:f.get('password'),create});$('#dialog').close();home();toast(create?'학교 계정이 준비되었어요.':'온라인 기록을 불러왔어요.');}catch(e){$('#form-error').textContent=cloud.authMessage(e);$('#login-submit').disabled=false;}};}
function conflictDialog(){accountDialog();}
function help(){modal('🌿 마을 모험 안내',`<div class="help-copy"><p>전체 지도에서 장소에 들어가면 그곳의 풍경과 대화가 펼쳐져요. 네 계절을 이어 가요. 지도를 누르거나 방향키·WASD로 움직일 수 있어요. 주민 가까이에서 E로 대화하고 J로 조사 수첩을 열어요. 아래쪽 만나기 버튼을 누르면 길을 따라 주민을 찾아가요.</p><p>계획을 고르면 짧은 작업 미션이 열려요. 도로 설계, 배관 끌어 잇기, 솔 청소, 잎 조사, 씨앗 심기, 농약 뿌리기, 사진 촬영, 컵 쌓기와 분리배출 등이 있어요. 도구를 끌거나 물건과 놓을 곳을 차례로 눌러도 돼요. 시간이 지나도 실패하지 않아요. 미션이 끝나면 계획을 실행해요.</p><p>선택의 결과는 실행한 뒤 나타나요. 실행한 선택에 따라 도로·하천·농장·축제장의 모습이 달라져요. 전체 지도에서도 변화가 남고, 이미 방문한 장소를 누르면 풍경과 기록을 다시 볼 수 있어요.</p><p>10개의 엔딩을 모아요. 앨범에는 새 엔딩의 단서가 있어요. 한 판 뒤에는 원하는 계절부터 다시 할 수 있어요.</p><p>계정으로 로그인하면 온라인에 10분마다 자동 저장해요. 기기를 바꾸기 전에는 ‘지금 저장하기’를 눌러 주세요. 공유 태블릿에서는 모험 뒤 ‘저장하고 로그아웃’을 눌러 주세요.</p><p>위쪽 소리 버튼으로 배경음악을 켜고 끌 수 있어요. 음표 버튼에서 음량을 조절해요. 결말을 만난 뒤에는 음악도 이야기 분위기에 맞게 바뀌어요.</p><p class="small-note">가상의 생태계 이야기입니다. 공사·농약·시설 관리는 담당 어른들이 합니다. 생물의 죽음을 직접 설명하는 결말이 있습니다. 배경은 AI로 제작한 일러스트입니다.</p></div>`);}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
cloud.onCloudStatus((status)=>{cloudStatus=status;if(status==='error'&&booting){booting=false;home();toast('온라인 연결을 확인해 주세요. 체험은 계속할 수 있어요.');}if(status==='saved')writeLocal();document.querySelectorAll('#save-cloud,[data-cloud-status]').forEach(b=>b.textContent=cloudLabel());});
home();cloud.initCloud((profile,remote)=>{booting=false;key=profile?'eco-village-'+profile.uid:'eco-village-guest-v2';const local=readLocal();let recover=false;if(profile&&remote){let base=-1;try{base=Number(localStorage.getItem(key+'-base')??-1);}catch{}recover=base===cloud.version()&&local.updatedAt>remote.updatedAt;state=recover?local:remote;const more=Object.keys(local.album).some(id=>!state.album[id]);state.album={...local.album,...state.album};recover ||= more;writeLocal();}else state=local;cloudStatus=profile?'online':'guest';reset();home();if(recover){cloud.queueCloud(state);toast('이 기기에 남은 기록도 이어서 저장해요.');}}).catch(()=>{booting=false;cloudStatus='error';home();toast('온라인 연결이 어려워요. 체험은 계속할 수 있어요.');});
